    "fiber_color_std": "Codice Colore Fibra — TIA-598-C",
    "fiber_color_note": "Le posizioni 13–24 ripetono gli stessi 12 colori. L'identificazione fisica utilizza una striscia nera o un anello attorno al secondo gruppo di 12 fibre.",
    "wiring_std": "Standard di Cablaggio",
    "cable_type": "Tipo di Cavo",
    "straight_through": "Diretto",
    "crossover": "Incrociato",
    "t568a_desc": "T568A — Preferito per installazioni residenziali e tratte orizzontali (TIA-568). Coppia verde sui pin 1–2. Le coppie 2 e 3 sono in ordine opposto rispetto al T568B.",
    "t568b_desc": "T568B — Dominante nelle implementazioni commerciali nordamericane. Coppia arancione sui pin 1–2. Elettricamente identico al T568A con le coppie 2 e 3 scambiate.",
    "crossover_desc": "Cavo incrociato: T568A sull'estremità A, T568B sull'estremità B. Scambia le coppie 2 e 3, consentendo collegamenti diretti da dispositivo a dispositivo (PC-PC, switch-switch) senza uno switch intermedio.",
