    "notes_reno": "Conservativo; il più lento a recuperare su percorsi ad alto BDP",
    "notes_cubic": "Migliore su LFN; default in Linux dal kernel 2.6.19",
    "notes_bbr": "Migliore throughput in caso di perdita; può causare accodamento se non sintonizzato",
    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "Ottimizzazione TCP Linux (sysctl)",
    "sysctl_subtitle": "Genera comandi sysctl para sintonizzare i buffer TCP di Linux e il controllo della congestione per i parametri del tuo percorso.",
    "sysctl_algo": "Algoritmo di Controllo della Congestione",
    "sysctl_apply_hint": "Applica con: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. I valori sono calcolati dal tuo BDP.",
    "ref_title": "Riferimento Algoritmo",
    "ref_reno_desc": "Algoritmo AIMD classico. Lo slow start raddoppia il cwnd ogni RTT fino a ssthresh. Il congestion avoidance aggiunge ~1 segmento per RTT. Su 3 ACK duplicati: ssthresh = cwnd/2, cwnd = ssthresh. Su timeout: cwnd = 1 MSS. Equo ma sottoutilizza i percorsi ad alto BDP dopo la perdita.",
    "ref_cubic_desc": "Default in Linux. Utilizza una funzione cubica W(t) = C(t-K)^3 + W_max (C=0,4, beta=0,7). Dopo la perdita, il cwnd scende al 70% di W_max, quindi cresce tramite la curva concavo-convessa. Più aggressivo di Reno sulle long-fat networks. K = (W_max * 0,3 / C)^(1/3).",
    "ref_bbr_desc": "Algoritmo basato su modello di Google. Stima la larghezza di banda del collo di bottiglia e l'RTT minimo invece di usare la perdita come segnale. Fases: Startup (guadagno 2,89x), Drain, ProbeBW (ciclo di guadagno a 8 fasi: 1,25/0,75/1...), ProbeRTT (4 segmenti circa ogni 10s). Ottiene il throughput completo anche con perdite.",
