    "plat_iosxe_notes": "Assicurarsi che il filesystem flash disponga di spazio libero sufficiente con \"show flash:\". Se si utilizza SCP, \"ip scp server enable\" deve essere configurato sul server, oppure il dispositivo deve avere il routing SSH abilitato.",
    "plat_iosxr_notes": "I filesystem IOS-XR usano disk0: o disk1: invece di flash:. I comandi SCP/SFTP in XR richiedono la password utente in modo interattivo. Il contesto di routing (VRF) può essere configurato a livello globale.",
    "plat_nxos_notes": "NX-OS usa bootflash: per impostazione predefinita. Verificare lo spazio del filesystem con \"dir bootflash:\". Il VRF deve avere raggiungibilità IP verso il server; controllare il routing predefinito o il VRF di gestione.",
    "plat_junos_notes": "Le copie dei file su Junos vengono inserite in /var/tmp/ o /var/db/config/. Usare \"show system storage\" per verificare lo spazio su disco. I trasferimenti TFTP possono richiedere configurazioni del protocollo di routing Junos o l'uso della parola chiave routing-instance.",
    "plat_eos_notes": "I dispositivi Arista usano flash:. Verificare con \"dir flash:\". Per un throughput elevato, Arista supporta copie HTTP/HTTPS native altamente ottimizzate.",
    "plat_fortios_notes": "Il ripristino TFTP di FortiOS sostituisce l'immagine di avvio e riavvia automaticamente il dispositivo. Usare con cautela. Salvare sempre prima i file di configurazione.",
    "plat_panos_notes": "Palo Alto PAN-OS richiede autorizzazioni amministratore CLI esplicite per eseguire i comandi di importazione del software. Il software può anche essere scaricato direttamente dagli aggiornamenti ufficiali del supporto Palo Alto.",
    "plat_linux_notes": "Verificare i permessi di lettura/scrittura della directory di destinazione. Assicurarsi che il client (scp, curl) sia installato. I trasferimenti HTTP/HTTPS tramite curl/wget sono altamente parallelizzabili.",
    "plat_f5_notes": "Verificare i processi bigstart e i permessi di route amministrativa di F5. La cartella di destinazione /shared/images/ è la posizione predefinita per i file ISO di F5.",
    "cmd_iosxe": "! Comando Cisco IOS/IOS-XE",
