    "randomize_ip": "Casuale",
    "double_nat_title": "Doppio NAT in distribuzioni CGNAT",
    "double_nat_body": "In una tipica distribuzione CGNAT, gli abbonati eseguono il NAT anche sul loro CPE — traducendo gli indirizzi {rfc1918} nel loro indirizzo 100.64.0.0/10 assegnato prima ancora che il traffico raggiunga il NAT del carrier. Questo doppio NAT interrompe l'UPnP e la mappatura automatica delle porte, complica il port forwarding manuale ed è un noto punto critico per il gaming, il VoIP e qualsiasi applicazione che richieda connessioni in entrata.",
    "hosts_hint": "Host interni simulati (limitati dalla dimensione del pool locale)",
    "subscribers_hint": "Abbonati / CPE simulati — a ciascuno viene assegnato un blocco di porte dedicato dal pool pubblico",
    "mode_desc_static": "Binding permanente 1:1 — ogni host interno viene mappato su un IP pubblico dedicato. Accesso bidirezionale abilitato.",
    "mode_desc_dynamic": "Allocazione del pool in ordine di arrivo. Le porte non vengono modificate. Le connessioni falliscono quando il pool è esaurito.",
    "mode_desc_pat": "Tutti gli host interni condividono il pool di IP pubblici tramite un'allocazione di porte univoca. L'esaurimento delle porte viene mostrato come connessioni interrotte.",
