    "sessions_per_host_hint": "Connessioni simultanee aperte da ogni host interno. Porte totali necessarie = host × sessioni.",
    "desc_strategy_dynamic": "Il PAT standard alloca le porte sorgente dinamicamente una alla volta man mano che le connessioni si aprono. Il valore qui rappresenta l'utilizzo di picco delle porte modellato per host per stimare la capacità aggregata.",
    "desc_strategy_deterministic": "Il CGNAT alloca in anticipo un blocco fisso e riservato di porte sorgente a ogni abbonato. Ciò garantisce la disponibilità delle porte e riduce il sovraccarico di syslog del 99% (viene registrata solo l'allocazione del blocco, non le singole sessioni), ma limita il numero totale di abbonati per IP pubblico.",
    "sim_scaled_pool_note": "*Simulazione di un pool ridotto di {total} porte ({perIp} porte/IP) per dimostrare visivamente l'esaurimento senza renderizzare migliaia di righe.",
