    "safe_nat_pool": "Sicuro (mappatura 1:1 completamente coperta).",
    "scenario_label": "Seleziona scenario doppio-NAT",
    "scenario_overlap_title": "Scenario 1: Sottoreti Sovrapposte (VPN IPsec)",
    "scenario_overlap_desc": "Due reti utilizzano lo stesso intervallo privato (es. 192.168.1.0/24). Per comunicare senza conflitti IP, entrambi i lati devono eseguire il NAT. L'Host A traduce in un IP di transito e l'Host B traduce in un IP di transito.",
    "scenario_cgnat_title": "Scenario 2: Carrier-Grade NAT (CGNAT) su NAT del Cliente",
    "scenario_cgnat_desc": "Il Service Provider alloca 100.64.0.0/10 (RFC 6598) al WAN del cliente. Il cliente esegue il NAT locale (192.168.1.0/24 -> 100.64.1.2) e il Provider esegue il CGNAT (100.64.1.2 -> IP pubblico) per risparmiare spazio IPv4.",
