    "err_invalid_global": "Formato della sottorete o dell'intervallo Inside Global non valido",
    "err_invalid_ip": "Formato dell'indirizzo IP non valido",
    "explanation_title": "Comprendere NAT vs. PAT",
    "explanation_intro": "Network Address Translation (NAT) e Port Address Translation (PAT) sono tecniche per mappare uno spazio di indirizzi IP su un altro, utilizzate principalmente per preservare i limitati indirizzi IPv4 pubblici o risolvere conflitti di sottorete.",
    "nat_expl_title": "1. Cos'è il NAT?",
    "nat_expl_desc": "Il NAT traduce gli indirizzi IP su una base 1-a-1. Può essere Statico (mappatura permanente di un IP privato su un IP pubblico, ideale per i server rivolti al pubblico) o Dinamico (alloca un IP pubblico da un pool a un host privato su richiesta. Una volta assegnati tutti gli IP pubblici, gli host successivi vengono bloccati finché un IP non viene liberato). I numeri di porta non vengono modificati.",
    "pat_expl_title": "2. Cos'è il PAT (NAT Overload)?",
    "pat_expl_desc": "Il PAT (o Port Address Translation / NAT Overload) traduce sia l'indirizzo IP che il numero di porta sorgente su una base molti-a-uno (N-a-1). Più host privati condividono un singolo indirizzo IP pubblico assegnando porte sorgente univoche (es. 192.168.1.10:5000 e 192.168.1.11:5000 mappano su 203.0.113.10:1024 e 203.0.113.10:1025). Questo è il metodo standard per i router domestici e l'accesso a Internet aziendale.",
    "comparison_table_title": "Riepilogo del Confronto",
    "comp_header_feature": "Funzionalità",
    "comp_header_nat": "NAT (1-a-1)",
    "comp_header_pat": "PAT (N-a-1 / Overload)",
