    "about_body": "iperf è uno strumento di misurazione attiva per la larghezza di banda massima ottenibile su reti IP. Un host funge da server (listener) e un altro si connette come client per inviare (o ricevere) traffico su TCP, UDP o SCTP, riportando throughput, jitter e perdita di pacchetti. iperf3 (binario iperf3) è una riscrittura moderna con output JSON e modalità reverse/bidirezionale; iperf2 (binario iperf) è multi-client e più robusto per Wi-Fi e multicast. I due NON sono compatibili a livello di protocollo — entrambi i lati devono eseguire la stessa versione.",
